def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"

    class Parser:
        def __init__(self, text):
            self.tokens = re.findall(
                r"\s*(<=|>=|<>|[A-Za-z]+[1-9][0-9]*|[0-9]+|[A-Za-z]+|[()+\-*/,=:<>])",
                text,
            )
            self.i = 0

        def peek(self):
            return self.tokens[self.i] if self.i < len(self.tokens) else None

        def take(self):
            token = self.peek()
            self.i += 1
            return token

        def expression(self):
            node = self.term()
            while self.peek() in ("+", "-"):
                op = self.take()
                node = ("bin", op, node, self.term())
            return node

        def term(self):
            node = self.unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                node = ("bin", op, node, self.unary())
            return node

        def unary(self):
            if self.peek() == "-":
                self.take()
                return ("neg", self.unary())
            return self.atom()

        def atom(self):
            token = self.take()
            if token == "(":
                node = self.expression()
                self.take()  # )
                return node
            if token is not None and token.isdigit():
                return ("num", int(token))
            if token in ("SUM", "MIN", "MAX"):
                self.take()  # (
                args = []
                while True:
                    first = self.expression()
                    if self.peek() == ":":
                        self.take()
                        second = self.take()
                        args.append(("range", first[1], second))
                    else:
                        args.append(("expr", first))
                    if self.peek() != ",":
                        break
                    self.take()
                self.take()  # )
                return ("func", token, args)
            if token == "IF":
                self.take()  # (
                left = self.expression()
                op = self.take()
                right = self.expression()
                self.take()  # ,
                yes = self.expression()
                self.take()  # ,
                no = self.expression()
                self.take()  # )
                return ("if", left, op, right, yes, no)
            return ("ref", token)

    def col_num(name):
        return ord(name[0]) - ord("A")

    def row_num(name):
        return int(name[1:]) - 1

    cache = {}
    active = set()

    def eval_cell(name):
        if name not in cells:
            return 0
        if name in cache:
            return cache[name]
        if name in active:
            return CYCLE

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            value = evaluate(Parser(content[1:]).expression())
        else:
            value = int(content)
        active.remove(name)
        cache[name] = value
        return value

    def evaluate(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return eval_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            op, left_node, right_node = node[1:]
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return DIV0
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[2]
            matched = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return evaluate(node[4] if matched else node[5])

        _, function, args = node
        values = []
        for arg in args:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                c1, c2 = col_num(start), col_num(end)
                r1, r2 = row_num(start), row_num(end)
                for row in range(min(r1, r2), max(r1, r2) + 1):
                    for col in range(min(c1, c2), max(c1, c2) + 1):
                        name = chr(ord("A") + col) + str(row + 1)
                        if name in cells:
                            value = eval_cell(name)
                            if isinstance(value, str):
                                return value
                            values.append(value)
            else:
                value = evaluate(arg[1])
                if isinstance(value, str):
                    return value
                values.append(value)

        if function == "SUM":
            return sum(values)
        if not values:
            return 0
        return min(values) if function == "MIN" else max(values)

    return {name: eval_cell(name) for name in cells}
